spec.acceptance_tests:
import { test, expect } from "vitest";
import { score_task_priority, urgency_bucket } from "./index.js";

test("REQ-1: Completed tasks score 0 regardless of due date or importance.", () => {
  const score = score_task_priority({ completed: true, importance: 5, due_epoch: 0 }, 100000);
  expect(score).toBe(0);
});

test("REQ-2: Overdue tasks gain 40 points per complete day late, capped at 120.", () => {
  // 4 days late: 4 * 40 = 160 capped at 120. Importance 0 -> total 120
  const score = score_task_priority({ completed: false, importance: 0, due_epoch: 0 }, 4 * 86400);
  expect(score).toBe(120);
});

test("REQ-3: Tasks due within 24 hours receive 80 urgency points; tasks due within 7 days receive 35 urgency points.", () => {
  const score24h = urgency_bucket(50000, 0);
  expect(score24h).toBe(80);
  const score7d = urgency_bucket(200000, 0);
  expect(score7d).toBe(35);
});

test("REQ-4: Importance is clamped between 0 and 5, adding 30 points per level.", () => {
  // due in >7d -> urgency 0; importance 3 -> 90
  const score = score_task_priority({ completed: false, importance: 3, due_epoch: 1000000 }, 0);
  expect(score).toBe(90);
});

test("REQ-5: Total score is non-negative and capped at 200.", () => {
  // urgency 120 + 30 * 5 = 270, capped at 200
  const score = score_task_priority({ completed: false, importance: 5, due_epoch: 0 }, 10 * 86400);
  expect(score).toBe(200);
});

implementation.portable_code:
export interface TaskView {
  completed: boolean;
  importance: number;
  due_epoch: number;
}

export function urgency_bucket(due_epoch: number, now_epoch: number): number {
  const delta = due_epoch - now_epoch;
  if (delta < 0) {
    const days_late = Math.floor((-delta) / 86400);
    const points = days_late * 40;
    return points > 120 ? 120 : points;
  }
  if (delta <= 86400) return 80;
  if (delta <= 604800) return 35;
  return 0;
}

export function score_task_priority(task: TaskView, now_epoch: number = Date.now()): number {
  if (task.completed) return 0;
  let importance = task.importance;
  if (importance < 0) importance = 0;
  if (importance > 5) importance = 5;
  const score = urgency_bucket(task.due_epoch, now_epoch) + 30 * importance;
  return score > 200 ? 200 : Math.max(0, score);
}
